    if (tier === 2) return Math.floor(d * 16 / 10);
    if (tier === 3) return Math.floor(Math.floor(d * 16 / 10) * 16 / 10);
    return d;
  }

  function score(sl, type, tier) {
    var sp = TURRETS[type];
