function rampartSimulate(createStrategy, seed, maxTicks) {
  // ---- Exact game rules (section 2) ----
  var TURRETS = {
    bolt:   { cost: 50,  dmg: 26,  period: 8,  range: 300, splash: 0,  slow: 0,  pierce: 0, ground: 1, air: 1 },
    cannon: { cost: 90,  dmg: 60,  period: 24, range: 260, splash: 90, slow: 0,  pierce: 0, ground: 1, air: 0 },
    frost:  { cost: 70,  dmg: 10,  period: 12, range: 240, splash: 0,  slow: 30, pierce: 0, ground: 1, air: 1 },
    lance:  { cost: 120, dmg: 180, period: 36, range: 360, splash: 0,  slow: 0,  pierce: 1, ground: 1, air: 0 },
    flak:   { cost: 80,  dmg: 40,  period: 10, range: 320, splash: 70, slow: 0,  pierce: 0, ground: 0, air: 1 }
  };
  var TYPE_INDEX = { bolt: 0, cannon: 1, frost: 2, lance: 3, flak: 4 };
  var SPAWN_ORDER = ['grunt', 'runner', 'wisp', 'brute', 'splitter', 'mender'];
  var ENEMY = {
    grunt:     { hp: 60,  speed: 10, bounty: 4, leak: 1, air: 0, first: 1, weight: 10 },
    runner:    { hp: 40,  speed: 20, bounty: 4, leak: 1, air: 0, first: 2, weight: 4 },
    wisp:      { hp: 50,  speed: 12, bounty: 6, leak: 2, air: 1, first: 3, weight: 3 },
    brute:     { hp: 150, speed: 6,  bounty: 9, leak: 3, air: 0, first: 4, weight: 3 },
    splitter:  { hp: 90,  speed: 8,  bounty: 6, leak: 2, air: 0, first: 6, weight: 2 },
    mender:    { hp: 70,  speed: 8,  bounty: 7, leak: 2, air: 0, first: 8, weight: 1 },
    splitling: { hp: 0,   speed: 12, bounty: 1, leak: 1, air: 0, first: 99, weight: 0 }
  };
  var SLOT_TILES = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  var GROUND = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  var AIR = [[0,6],[21,6],[21,11],[23,11]];

  function buildRoute(pts) {
    var segs = [], total = 0;
    for (var i = 0; i < pts.length - 1; i++) {
      var x0 = pts[i][0] * 100 + 50, y0 = pts[i][1] * 100 + 50;
      var x1 = pts[i + 1][0] * 100 + 50, y1 = pts[i + 1][1] * 100 + 50;
      var len = Math.abs(x1 - x0) + Math.abs(y1 - y0);
      segs.push({ x0: x0, y0: y0, x1: x1, y1: y1, start: total, len: len });
      total += len;
    }
    return { segs: segs, total: total };
  }
  var GROUND_ROUTE = buildRoute(GROUND);
  var AIR_ROUTE = buildRoute(AIR);

  function routePos(route, p) {
    var segs = route.segs;
    for (var i = 0; i < segs.length; i++) {
      var s = segs[i];
      if (p <= s.start + s.len || i === segs.length - 1) {
        var d = p - s.start;
        if (d < 0) d = 0;
        if (d > s.len) d = s.len;
        if (s.x1 !== s.x0) return { x: s.x0 + (s.x1 > s.x0 ? d : -d), y: s.y0 };
        return { x: s.x0, y: s.y0 + (s.y1 > s.y0 ? d : -d) };
      }
    }
    var l = segs[segs.length - 1];
    return { x: l.x1, y: l.y1 };
  }

  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return (t ^ (t >>> 14)) >>> 0;
  }; }
  var rng = mulberry32(seed >>> 0);

  // HP multiplier m(w): m(1) = 1000, m(w) = floor(m(w-1) * 108 / 100)
  var mTable = [1000, 1000];
  function multAt(w) {
    while (mTable.length <= w) mTable.push(Math.floor(mTable[mTable.length - 1] * 108 / 100));
    return mTable[w];
  }

  function composeWave(w) {
    var types = [], total = 0;
    for (var i = 0; i < SPAWN_ORDER.length; i++) {
      var e = ENEMY[SPAWN_ORDER[i]];
      if (e.first <= w) { types.push(SPAWN_ORDER[i]); total += e.weight; }
    }
    var count = 4 + Math.floor(3 * w / 5);
    var out = [];
    for (var k = 0; k < count; k++) {
      var r = rng() % total;
      for (var j = 0; j < types.length; j++) {
        var wt = ENEMY[types[j]].weight;
        if (r < wt) { out.push(types[j]); break; }
        r -= wt;
      }
    }
    return out;
  }

  var log = [];
  function addLog(t, code, a, b) { log.push([t, code, a, b]); }

  var gold = 250, baseHp = 10;
  var tick = 0, wave = 0, nextId = 1, fallTick = -1, endTick = maxTicks;
  var enemies = [];
  var slots = [];
  for (var s = 0; s < 16; s++) {
    slots.push({ slot: s, x: SLOT_TILES[s][0] * 100 + 50, y: SLOT_TILES[s][1] * 100 + 50, turret: null });
  }
  var queue = [];
  var current = null, nextComposition = null;
  var strategy = null;
  try { strategy = createStrategy(); } catch (e) { strategy = null; }
  var targetFn = (strategy && typeof strategy.target === 'function') ? strategy.target : null;
  var planFn = (strategy && typeof strategy.plan === 'function') ? strategy.plan : null;

  function tierDamage(dmg, tier) {
    if (tier === 1) return dmg;
    var d = Math.floor(dmg * 16 / 10);
    if (tier === 2) return d;
    return Math.floor(d * 16 / 10);
  }
  function turretRange(type, tier) { return TURRETS[type].range + (tier - 1) * 30; }
  function armorFor(type, w) {
    if (type === 'grunt') return Math.floor(w / 4);
    if (type === 'brute') return 6 + w;
    return 0;
  }

  function enemyView(e) {
    return {
      id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y,
      air: e.air, armor: e.armor, speed: e.speed, slowed: e.slow > 0 ? 1 : 0,
      remaining: e.route.total - e.progress
    };
  }
  function makeState() {
    var slotViews = [];
    for (var i = 0; i < 16; i++) {
      var t = slots[i].turret;
      slotViews.push({
        slot: i, x: slots[i].x, y: slots[i].y,
        turret: t ? { type: t.type, tier: t.tier, spent: t.spent } : null
      });
    }
    var views = [];
    for (var j = 0; j < enemies.length; j++) views.push(enemyView(enemies[j]));
    return {
      tick: tick, wave: wave, gold: gold, baseHp: baseHp,
      slots: slotViews, enemies: views,
      nextWave: nextComposition ? nextComposition.slice() : []
    };
  }

  function applyAction(act) {
    if (!act || typeof act !== 'object') return;
    var op = act.op;
    var slotIdx = act.slot;
    if (typeof slotIdx !== 'number' || slotIdx < 0 || slotIdx > 15 || Math.floor(slotIdx) !== slotIdx) return;
    var sl = slots[slotIdx];
    if (op === 'build') {
      if (typeof act.type !== 'string' || !Object.prototype.hasOwnProperty.call(TURRETS, act.type)) return;
      if (sl.turret) return;
      var spec = TURRETS[act.type];
      if (gold < spec.cost) return;
      gold -= spec.cost;
      sl.turret = { type: act.type, tier: 1, spent: spec.cost, cooldown: 0 };
      addLog(tick, 'B', slotIdx, TYPE_INDEX[act.type]);
    } else if (op === 'upgrade') {
      var t = sl.turret;
      if (!t || t.tier >= 3) return;
      var cost = t.tier === 1 ? TURRETS[t.type].cost : 2 * TURRETS[t.type].cost;
      if (gold < cost) return;
      gold -= cost;
      t.tier += 1;
      t.spent += cost;
      addLog(tick, 'U', slotIdx, t.tier);
    } else if (op === 'sell') {
      if (!sl.turret) return;
      gold += Math.floor(sl.turret.spent * 70 / 100);
      sl.turret = null;
      addLog(tick, 'S', slotIdx, 0);
    }
  }

  function sortQueue() {
    queue.sort(function (a, b) {
      if (a.tick !== b.tick) return a.tick - b.tick;
      if (a.wave !== b.wave) return a.wave - b.wave;
      return a.idx - b.idx;
    });
  }

  function startWave(w) {
    wave = w;
    gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * w;
    current = composeWave(w);
    nextComposition = composeWave(w + 1);
    if (planFn) {
      var actions = null;
      try { actions = planFn(makeState()); } catch (e) { actions = null; }
      if (actions && typeof actions.length === 'number') {
        var n = Math.min(32, actions.length);
        for (var i = 0; i < n; i++) {
          try { applyAction(actions[i]); } catch (e2) { /* invalid action: skipped */ }
        }
      }
    }
    for (var k = 0; k < current.length; k++) {
      queue.push({ tick: tick + 4 * k, wave: w, idx: k, type: current[k] });
    }
    sortQueue();
  }

  function spawnEnemy(type, w, progress, maxHp, route) {
    var spec = ENEMY[type];
    var p = routePos(route, progress);
    var e = {
      id: nextId++, type: type, wave: w,
      hp: maxHp, maxHp: maxHp,
      progress: progress, speed: spec.speed,
      armor: armorFor(type, w), slow: 0, age: 0, air: spec.air,
      x: p.x, y: p.y, route: route
    };
    enemies.push(e);
    return e;
  }

