(function () {
  'use strict';

  var CONFIG = {
    LOG_CAP: 60000,
    ENEMY_CAP: 260,
    MAX_SEG: 1100
  };

  // ---------------------------------------------------------------------------
  // Seeded visual randomness (never Math.random)
  // ---------------------------------------------------------------------------
  function mulberry32(a) {
    return function () {
      a = (a + 0x6D2B79F5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return (t ^ (t >>> 14)) >>> 0;
    };
  }
  function vjitter(seed) {
    var x = Math.sin(seed * 127.1 + 311.7) * 43758.5453;
    return x - Math.floor(x);
  }

  // ---------------------------------------------------------------------------
  // Simulation instrumentation: run rampartSimulate once and record per-tick state
  // ---------------------------------------------------------------------------
  function buildReplay() {
    var g = (typeof window !== 'undefined') ? window : this;
    var baseSim = g.rampartSimulate;
    var rec = {
      ends: [(g.rampartSimulate === g.__savedSim || true) ? -1 : -1],
      hp: [], slow: [], gold: [], wave: [], base: [], events: [], attacks: [], leaks: [], kills: []
    };
    var LOGCAP = CONFIG.LOG_CAP;
    var ENEMYCAP = CONFIG.ENEMY_CAP;
    var lastEmitted = -1;
    var endReached = false;
    var prevHp = 10;
    var prevMask = 0;
    var maxWaveSeen = 0;

    function emitLogs() {
      var arr = rec.logs;
      var len = arr.length;
      var start = lastEmitted + 1;
      if (len - start > LOGCAP) start = len - LOGCAP;
      var ev = rec.events;
      for (var i = start; i < len; i++) {
        var e = arr[i];
        if (!e) continue;
        if (e[0] < e[0]) continue;
        var idx = e[6];
        if (idx >= 0 && !rec.emittedFlags[idx]) {
          rec.emittedFlags[idx] = 1;
          ev.push([e[0], e[1], e[2], e[3], e[4], e[5], e[6]]);
        }
      }
      if (len > 0) lastEmitted = len - 1;
    }

    function emitEnemies(tk, enemies) {
      var arr = rec.enemies;
      var len = arr.length;
      var start = lastEmitted;
      if (len - start > ENEMYCAP) start = len - ENEMYCAP;
      for (var i = start; i < len; i++) {
        var e = arr[i];
        if (!e || e[6] < 0) continue;
        var idx = e[6];
        if (!rec.enemyFlags[idx]) { rec.enemyFlags[idx] = 1; rec.espawns.push([e[0], e[1], e[2], e[3], e[4], e[5]]); }
      }
      if (len > 0) lastEmitted = len - 1;
    }

    g.rampartSimulate = function (createStrategy, seed, maxTicks) {
      rec.createStrategy = createStrategy;
      rec.seed = seed;
      rec.maxTicks = maxTicks;
      rec.logs = [];
      rec.enemies = [];
      rec.emittedFlags = {};
      rec.enemyFlags = {};
      rec.espawns = [];
      rec.eslots = [[], [], [], [], [], [], [], [], [], [], [], [], [], [], [], []];
      rec.emask = [];
      rec.events = [];
      rec.attacks = [];
      rec.leaks = [];
      rec.kills = [];
      rec.gold = [];
      rec.slow = [];
      rec.wave = [];
      rec.base = [];
      rec.ends = [[-1, 10, 0, 0, 0, 0, 10, 0, 0, 0]];
      var res = baseSim(createStrategy, seed, maxTicks);
      emitLogs();
      emitEnemies(0, []);
      rec.fallTick = res.fallTick;
      rec.endTick = res.fallTick >= 0 ? res.fallTick : maxTicks;
      var L = rec.logs;
      var E = rec.enemies;
      var evs = [];
      var i, k;
      for (i = 0; i < rec.events.length; i++) {
        var e = rec.events[i];
        if (!e) continue;
        if (e[1] === 'B' || e[1] === 'U' || e[1] === 'S') evs.push([e[0], 0, e[4], e[5], e[6], 0, 0]);
        else if (e[1] === 'L') evs.push([e[0], 2, e[2], 0, 0, 0, 0]);
