      for (i = 0; i < rec.leaks.length; i++) all.push(rec.leaks[i]);
      for (i = 0; i < rec.kills.length; i++) all.push(rec.kills[i]);
      all.sort(function (a, b) { return (a[0] - b[0]) || (a[1] - b[1]); });
      var curA = -1, prevSlot = -1, lastTick = -1;
      var live = {};
      var openSeg = {};
      var n = 0;
      for (i = 0; i < all.length; i++) {
        var a = all[i];
        var tk = a[0];
        if (tk < prevSlot) tk = prevSlot;
        prevSlot = tk;
        while (curA < a[1] - 1) {
          curA++;
          var L2 = [];
          while (++lastTick < tk) { L2.push(tk); }
          if (lastTick === tk - 1) lastTick = tk;
          atk.push(L2.length ? L2 : L2);
        }
        while (lastTick < tk) { atk[curA].push(tk); lastTick = tk; }
        if (a[2] === 1) { live[a[3]] = a[4]; }
        else if (a[2] === 3) { for (k = 0; k < atk.length; k++) { if (atk[k] && atk[k].length === tk) { atk[k].push(1); } } }
        else { if (live[a[3]] !== undefined) { delete live[a[3]]; } }
