      }
      for (curA = curA + 1; curA < 16; curA++) atk.push([]);
      // pad slices for ticks after the end
      rec.endTick = Math.min(rec.endTick, maxTicks);
      for (var s = 0; s < 16; s++) {
        var arrS = atk[s];
        if (!arrS) { atk[s] = []; continue; }
        while (arrS.length <= rec.endTick) arrS.push(0);
        var padded = [0];
        for (k = 1; k < arrS.length; k++) padded.push(arrS[k]);
        atk[s] = padded;
      }
      // Move segment arrays: ensure no spurious attack slices are missing
      rec.goldDefault = 0;
      return res;
    };

    // Internal state exposed to the recorder through the patched functions below
    g.__rec = rec;
    g.__emitLogs = emitLogs;

    var res = null;
    return {
      rec: rec
    };
  }

  // ---------------------------------------------------------------------------
  // Main
  // ---------------------------------------------------------------------------
  var canvas = document.getElementById('stage');
  var countdownEl = document.getElementById('countdown');
  var btnToggle = document.getElementById('btn-toggle');
  var btnRefire = document.getElementById('btn-refire');
  var iconPause = document.getElementById('icon-pause');
  var iconPlay = document.getElementById('icon-play');
  var scrubber = document.getElementById('scrubber');
  var speedPills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));

  var DURATION = 100;
  var TPS = 20;
  var MAXTICKS = 2019;

  var renderer;
  try {
    renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true });
  } catch (e) {
    renderer = null;
  }
  if (renderer) {
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(window.innerWidth, window.innerHeight, false);
    renderer.outputEncoding = THREE.sRGBEncoding;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.05;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.autoClear = false;
  }

