class WS:
    def __init__(self, url):
        # ws://127.0.0.1:PORT/path
        rest = url[5:]
        hostport, path = rest.split('/', 1)
        host, port = hostport.split(':')
        self.sock = socket.create_connection((host, int(port)), timeout=60)
        key = base64.b64encode(os.urandom(16)).decode()
        req = ('GET /' + path + ' HTTP/1.1\r\nHost: ' + hostport + '\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n'
               'Sec-WebSocket-Key: ' + key + '\r\nSec-WebSocket-Version: 13\r\n\r\n')
        self.sock.sendall(req.encode())
        buf = b''
        while b'\r\n\r\n' not in buf:
            buf += self.sock.recv(4096)
        self.buf = buf.split(b'\r\n\r\n', 1)[1]
        self.next_id = 0

    def send(self, method, params=None):
        self.next_id += 1
        mid = self.next_id
        payload = json.dumps({'id': mid, 'method': method, 'params': params or {}}).encode()
        header = bytearray([0x81])
        ln = len(payload)
        mask = os.urandom(4)
        if ln < 126:
            header.append(0x80 | ln)
        elif ln < 65536:
            header.append(0x80 | 126); header += struct.pack('>H', ln)
        else:
            header.append(0x80 | 127); header += struct.pack('>Q', ln)
        header += mask
        masked = bytes(payload[i] ^ mask[i % 4] for i in range(ln))
        self.sock.sendall(bytes(header) + masked)
        while True:
            msg = self._recv_msg()
            if msg is None:
                raise RuntimeError('connection closed')
            if msg.get('id') == mid:
                return msg

    def _read(self, n):
        while len(self.buf) < n:
            chunk = self.sock.recv(65536)
            if not chunk:
                return None
            self.buf += chunk
        out, self.buf = self.buf[:n], self.buf[n:]
        return out

    def _recv_msg(self):
        h = self._read(2)
        if not h:
            return None
        b1, b2 = h[0], h[1]
        ln = b2 & 0x7f
        if ln == 126:
            ln = struct.unpack('>H', self._read(2))[0]
        elif ln == 127:
            ln = struct.unpack('>Q', self._read(8))[0]
        data = self._read(ln) if ln else b''
        op = b1 & 0x0f
        if op == 8:
            return None
        try:
            return json.loads(data.decode('utf-8', 'replace'))
        except Exception:
            return {}

    def close(self):
        try:
            self.sock.close()
        except Exception:
            pass


class Browser:
    def __init__(self, width=1280, height=650, port=9333):
        self.port = port
        self.proc = subprocess.Popen([SHELL, '--no-sandbox', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--remote-debugging-port=' + str(port),
                                      '--user-data-dir=' + os.path.join(DEV, '..', '.cache', 'ud-cdp'),
                                      '--window-size=%d,%d' % (width, height), '--hide-scrollbars', 'about:blank'],
                                     stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        for _ in range(100):
            try:
                data = json.loads(urllib.request.urlopen('http://127.0.0.1:%d/json' % port, timeout=1).read())
                for t in data:
                    if t.get('type') == 'page':
                        self.ws = WS(t['webSocketDebuggerUrl'])
                        self.target = t
                        break
                if hasattr(self, 'ws'):
                    break
            except Exception:
                time.sleep(0.2)
        else:
            raise RuntimeError('no debug target')
        self.events = []
        self.send('Page.enable')
        self.send('Runtime.enable')
        self.width = width
        self.height = height

    def send(self, method, params=None):
        r = self.ws.send(method, params)
        if 'error' in r:
            raise RuntimeError(method + ': ' + json.dumps(r['error']))
        return r.get('result', {})

    def navigate(self, url):
        self.send('Page.navigate', {'url': url})

    def evaluate(self, expr):
        r = self.send('Runtime.evaluate', {'expression': expr, 'returnByValue': True, 'awaitPromise': True})
        if 'exceptionDetails' in r:
            return {'__error': r['exceptionDetails'].get('text'), 'detail': str(r['exceptionDetails'].get('exception', {}).get('description', ''))[:2000]}
        return r.get('result', {}).get('value')

    def screenshot(self, path):
        r = self.send('Page.captureScreenshot', {'format': 'png'})
        open(path, 'wb').write(base64.b64decode(r['data']))

    def close(self):
        try:
            self.ws.close()
        except Exception:
            pass
        self.proc.terminate()
        try:
            self.proc.wait(timeout=10)
        except Exception:
            self.proc.kill()


