def remove_block_braces(src, start_re):
    pos = 0
    while True:
        m = re.compile(start_re, re.M).search(src, pos)
        if not m:
            return src
        k = src.find('{', m.end() - 1)
        if k < 0:
            return src
        depth = 0
        j = k
        in_s = None
        while j < len(src):
            ch = src[j]
            if in_s:
                if ch == '\\':
                    j += 2
                    continue
                if ch == in_s:
                    in_s = None
            else:
                if ch in '"\'':
                    in_s = ch
                elif ch == '{':
                    depth += 1
                elif ch == '}':
                    depth -= 1
                    if depth == 0:
                        break
            j += 1
        end = src.find('\n', j)
        end = len(src) if end < 0 else end + 1
        src = src[:m.start()] + src[end:]
        pos = m.start()


def remove_if_iife(src, start_re):
    """Remove 'if (...) {' / 'window.X = (function () {' ... through the matching '})();' or '}'."""
    m = re.compile(start_re, re.M).search(src)
    if not m:
        return src
    k = src.find('{', m.end() - 1)
    depth = 0
    j = k
    in_s = None
    while j < len(src):
        ch = src[j]
        if in_s:
            if ch == '\\':
                j += 2
                continue
            if ch == in_s:
                in_s = None
        else:
            if ch in '"\'':
                in_s = ch
            elif ch == '{':
                depth += 1
            elif ch == '}':
                depth -= 1
                if depth == 0:
                    break
        j += 1
    end = src.find('\n', j)
    end = len(src) if end < 0 else end + 1
    return src[:m.start()] + src[end:]


