"""Clean the known-good dev main script (extracted from index_test.html) into production form."""
import re

src = open('main_dev.js').read()


def find_block_end(text, start):
    """Return index just after the line that closes the brace opened at/after start."""
    k = text.find('{', start)
    depth = 0
    j = k
    in_s = None
    while j < len(text):
        ch = text[j]
        if in_s:
            if ch == '\\':
                j += 2
                continue
            if ch == in_s:
                in_s = None
            j += 1
            continue
        if ch in '"\'':
            in_s = ch
        elif ch == '{':
            depth += 1
        elif ch == '}':
            depth -= 1
            if depth == 0:
                break
        j += 1
    e = text.find('\n', j)
    return len(text) if e < 0 else e + 1


def remove_statement(src, needle):
    """Remove a complete statement that starts on the line containing needle (through ';' at depth 0)."""
    i = src.find(needle)
    if i < 0:
        return src
    ls = src.rfind('\n', 0, i) + 1
    # find ';' at brace/paren depth 0
    depth = 0
    j = i
    in_s = None
    while j < len(src):
        ch = src[j]
        if in_s:
            if ch == '\\':
                j += 2
                continue
            if ch == in_s:
                in_s = None
        else:
            if ch in '"\'':
                in_s = ch
