"""Assemble the final page: clean graded sim + recorder-enabled demo sim + wiring."""
import os, re

DEV = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(os.path.dirname(DEV), 'index.html')
s = open(OUT).read()

# ---------------------------------------------------------------------------
# 1. graded sim section  <- sim_final.js (pure, no recorder)
# ---------------------------------------------------------------------------
graded = open(os.path.join(DEV, 'sim_final.js')).read().rstrip()
a = s.find('<script id="rampart-sim">')
b = s.find('</script>', a)
assert a > 0
s = s[:a + len('<script id="rampart-sim">\n')] + graded + '\n' + s[b:]

# ---------------------------------------------------------------------------
# 2. recorder-enabled copy of the sim, used only to drive the visuals
# ---------------------------------------------------------------------------
rec = graded
rec = rec.replace('function rampartSimulate(createStrategy, seed, maxTicks) {',
                  'function rampartSimulateRec(createStrategy, seed, maxTicks) {', 1)
# addLog: also keep the event log for the replay
rec = rec.replace("""  function addLog(t, code, a, b) {
    log.push([t, code, a, b]);""", """  function addLog(t, code, a, b) {
    log.push([t, code, a, b]);
    rlog.push([t, code, a, b]);""", 1)
rec = rec.replace('  var log = [];', '  var log = [];\n  var rlog = [];', 1)
# recorder state just before the main loop
rec = rec.replace('  for (tick = 0; tick <= maxTicks; tick++) {', """  var recBuild = [], recAct = [], recKill = [], recHp = [], recGold = [], recSlow = [], recAges = [], recLeak = [], recWaveL = [], recSnaps = [], recSplits = [];
  for (var rs = 0; rs < 16; rs++) { recBuild.push([]); recAct.push([]); }
  for (tick = 0; tick <= maxTicks; tick++) {""", 1)
rec = rec.replace('    if (tick >= 20 && (tick - 20) % 40 === 0) startWave(', '    if (tick >= 20 && (tick - 20) % 40 === 0) recWaveL.push([tick, Math.floor((tick - 20) / 40) + 1]);\n    if (tick >= 20 && (tick - 20) % 40 === 0) startWave(', 1)
# builds / upgrades / sells
rec = rec.replace("      addLog(tick, 'B', slotIdx, TYPE_INDEX[act.type]);", "      addLog(tick, 'B', slotIdx, TYPE_INDEX[act.type]);\n      recBuild[slotIdx].push([tick, TYPE_INDEX[act.type], 1, gold, 0, 0]);", 1)
rec = rec.replace("      addLog(tick, 'U', slotIdx, t.tier);", "      addLog(tick, 'U', slotIdx, t.tier);\n      recBuild[slotIdx].push([tick, TYPE_INDEX[t.type], 2, gold, t.tier, 0]);", 1)
rec = rec.replace("      addLog(tick, 'S', slotIdx, 0);", "      addLog(tick, 'S', slotIdx, 0);\n      recBuild[slotIdx].push([tick, -1, 3, gold, 0, 0]);", 1)
# leaks and kills
rec = rec.replace("        addLog(tick, 'L', e.id, baseHp);", "        addLog(tick, 'L', e.id, baseHp);\n        recLeak.push([tick, e.id, e.x, e.y, e.air, baseHp]);", 1)
rec = rec.replace("          addLog(tick, 'K', de.id, si);", "          addLog(tick, 'K', de.id, si);\n          recKill.push([tick, de.id, de.x, de.y, de.air, si]);", 1)
rec = rec.replace("            var slHp = Math.max(1, Math.floor(de.maxHp / 4));", "            recSplits.push([tick, de.id, de.wave, de.x, de.y, Math.max(1, Math.floor(de.maxHp / 4))]);\n            var slHp = Math.max(1, Math.floor(de.maxHp / 4));", 1)
# attacks (per firing turret)
rec = rec.replace('      tu.cooldown = spec2.period;', '      recAct[si].push([tick, chosen.id, chosen.x, chosen.y, chosen.air, 0]);\n      tu.cooldown = spec2.period;', 1)
# per-tick snapshot right after the move step
rec = rec.replace('    if (fell) break;', """    var __snap = [];
    for (var rq = 0; rq < enemies.length; rq++) {
      var re = enemies[rq];
      __snap.push([re.id, re.type, re.x, re.y, re.hp, re.slow > 0 ? 1 : 0, re.progress, re.air ? 1 : 0]);
    }
    recSnaps.push(__snap);
    recHp.push(baseHp);
    recGold.push(gold);
    var __sl = [], __ag = [];
    for (var rq2 = 0; rq2 < enemies.length; rq2++) { __sl.push(enemies[rq2].slow); __ag.push(enemies[rq2].age); }
    recSlow.push(__sl);
    recAges.push(__ag);
    if (fell) break;""", 1)
# return the replay data on a non-enumerable field
rec = rec.replace('  recOut.hash = hex;', '''  recOut.hash = hex;
  Object.defineProperty(recOut, 'replay', { enumerable: false, value: {
    snapshots: recSnaps, hp: recHp, gold: recGold, slow: recSlow, ages: recAges, attacks: recAct, builds: recBuild,
    leaks: recLeak, kills: recKill, splits: recSplits, waveStarts: recWaveL, log: rlog, fallTick: fallTick, endTick: endTick
  } });''', 1)

s = s.replace('</script>\n<script>\nwindow.BENCH_REPORT', '</script>\n<script id="rampart-demo-sim">\n' + rec + '\n</script>\n<script>\nwindow.BENCH_REPORT', 1)

# ---------------------------------------------------------------------------
# 3. main invocation: graded sim once (reference), recorder sim for the visuals
# ---------------------------------------------------------------------------
old_inv = re.search(r'try \{\n  window\.RAMPART_RECORD = REC;.*?\ndelete window\.RAMPART_RECORD;', s, re.S)
assert old_inv, 'invocation block not found'
new_inv = '''var gradedRes = null;
var demoRes = null;
var buildMs = 0;
try {
  var __t0 = (window.performance && performance.now) ? performance.now() : 0;
  gradedRes = window.rampartSimulate(window.createStrategy, 42, MAXTICKS);
  demoRes = rampartSimulateRec(window.createStrategy, 42, MAXTICKS);
  buildMs = ((window.performance && performance.now) ? performance.now() : 0) - __t0;
} catch (e) {
  gradedRes = gradedRes || { score: 0, fallTick: -1, log: [], hash: '' };
}
var simRes = demoRes || gradedRes;'''
s = s[:old_inv.start()] + new_inv + s[old_inv.end():]

# replay data is now on the demo result's `replay` field
s = s.replace("var RDATA = (simRes && simRes.replay) ? simRes.replay :", "var RDATA = (demoRes && demoRes.replay) ? demoRes.replay :")
# RDATA no longer contains the event log; attach graded log for the audio-free replay
s = s.replace("for (var __k in RDATA) REC[__k] = RDATA[__k];", "for (var __k in RDATA) REC[__k] = RDATA[__k];\nREC.log = gradedRes ? gradedRes.log : [];\nREC.graded = gradedRes;")

open(OUT, 'w').write(s)
print('written', len(s))
print('RAMPART_RECORD refs:', s.count('RAMPART_RECORD'))
print('rampartSimulateRec refs:', s.count('rampartSimulateRec'))

