"""Build sim_demo.js: the graded sim plus a side-recorder that only observes.

The recorder never appends per-tick arrays.  Each enemy is recorded once at spawn
(type, spawn tick, max hp, air) and then sampled once per tick for (progress, slow).
Kills/leaks set the last alive tick.  `replay` on the result carries:
  life        -- [{id,type,t0,hp0,air,end,prog[],slow[]}]
  log         -- the graded log entries, each with a compact pre-rendered line
  attacks     -- per-slot "tick:targetId" strings
  builds/leaks/kills/endTick/fallTick
The rules and the returned {score, fallTick, log, hash} are unchanged.
"""
import os

DEV = os.path.dirname(os.path.abspath(__file__))
graded = open(os.path.join(DEV, 'sim_final.js')).read().rstrip()
rec = graded


def sub(old, new, count=1):
    global rec
    assert old in rec, 'missing: ' + old[:70]
    rec = rec.replace(old, new, count)


sub('function rampartSimulate(createStrategy, seed, maxTicks) {',
    'function rampartSimulateRec(createStrategy, seed, maxTicks) {')

# log entries keep the pre-rendered line for the page's parser
sub("""    log.push([t, code, a, b]);""",
    """    log.push([t, code, a, b, '[' + t + ',"' + code + '",' + a + ',' + b + ']']);""")

# side recorders
sub("""  var gold = 250, baseHp = 10;""",
    """  var LIFE = [], ATKS = [], BLDS = [], ATI = 0;
  for (var _b = 0; _b < 16; _b++) BLDS.push([]);
  var WAREG = [];
  var gold = 250, baseHp = 10;""")

# waves
sub("""  function startWave(w) {
    wave = w;""", """  function startWave(w) {
    WAREG.push([tick, w]);
    wave = w;""")

# builds / upgrades / sells
sub("""      addLog(tick, 'B', slotIdx, TYPE_INDEX[act.type]);""",
    """      addLog(tick, 'B', slotIdx, TYPE_INDEX[act.type]);
      BLDS[slotIdx].push([tick, TYPE_INDEX[act.type], 1, gold, 0, 0]);""")
sub("""      addLog(tick, 'U', slotIdx, t.tier);""",
    """      addLog(tick, 'U', slotIdx, t.tier);
      BLDS[slotIdx].push([tick, TYPE_INDEX[t.type], 2, gold, t.tier, 0]);""")
sub("""      addLog(tick, 'S', slotIdx, 0);""",
    """      addLog(tick, 'S', slotIdx, 0);
      BLDS[slotIdx].push([tick, -1, 3, gold, 0, 0]);""")

# spawns
sub("""    enemies.push(e);
    return e;""", """    enemies.push(e);
    LIFE.push({ id: e.id, type: type, t0: tick, hp0: maxHp, air: spec.air ? 1 : 0, prog: [progress], slow: [0] });
    return e;""")

# per-tick sample of every living enemy (before it moves)
sub("""    // 3. move (ascending id); leaks and falls
    var fell = false;""", """    // 3. move (ascending id); leaks and falls
    var fell = false;
    var _S = {};
    if (tick > 0) {
      for (var _i = 0; _i < LIFE.length; _i++) {
        var _L = LIFE[_i];
        if (_L.t0 === tick || _L.end !== undefined) continue;
        _S[_L.id] = _L;
      }
      for (var _m = 0; _m < enemies.length; _m++) {
        var _e = enemies[_m], _r = _S[_e.id];
        if (!_r) continue;
        _r.prog.push(_e.progress);
        _r.slow.push(_e.slow > 0 ? 1 : 0);
      }
    }""")

# leaks / kills close the life
sub("""        addLog(tick, 'L', e.id, baseHp);""",
    """        addLog(tick, 'L', e.id, baseHp);
        if (_S[e.id]) _S[e.id].end = tick;""")
sub("""          addLog(tick, 'K', de.id, si);""",
    """          addLog(tick, 'K', de.id, si);
          if (_S[de.id]) _S[de.id].end = tick;""")

# attacks
sub("""      tu.cooldown = spec2.period;""",
    """      if (!ATKS[si]) ATKS[si] = [];
      ATKS[si].push(tick + ':' + chosen.id);
      tu.cooldown = spec2.period;""")

# payload
sub("""  recOut.hash = hex;""", """  recOut.hash = hex;
  Object.defineProperty(recOut, 'replay', { enumerable: false, value: {
    life: LIFE, log: log, attacks: ATKS, builds: BLDS, waves: WAREG,
    endTick: endTick, fallTick: fallTick
  } });""")

open(os.path.join(DEV, 'sim_demo.js'), 'w').write(rec)
print('demo written', len(rec))

