import os
DEV = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(os.path.dirname(DEV), 'index.html')
s = open(OUT).read()


def sub(old, new, count=1):
    global s
    assert old in s, 'missing: ' + old[:80]
    s = s.replace(old, new, count)


# wall-clock start: the countdown is measured from the moment the scene starts
# rather than from the (possibly late) first animation frame
sub("""function startFrames() {
  if (started) return;
  started = true;""", """function startFrames() {
  if (started) return;
  started = true;
  lastNow = (window.performance && performance.now) ? performance.now() : 0;""")

# the first frame is already counted from a known origin: no need to discard it
sub("""function stepFrame(now) {
  var rawDt = lastNow === null ? 0 : (now - lastNow) / 1000;
  lastNow = now;
  var dt = Math.min(rawDt, 0.1);
  if (!firstFrameDone) {
    firstFrameDone = true;
    countdownElapsed = 0;
    setCountdown('3', true);
    setState(STATE.COUNTDOWN);
    renderAt(0);
    return;
  }""", """function stepFrame(now) {
  var rawDt = lastNow === null ? 0 : (now - lastNow) / 1000;
  lastNow = now;
  var dt = Math.max(0, Math.min(rawDt, 0.1));
  if (!firstFrameDone) {
    firstFrameDone = true;
    countdownElapsed = 0;
    setCountdown('3', true);
    setState(STATE.COUNTDOWN);
    renderAt(0);
    return;
  }""")

open(OUT, 'w').write(s)
print('clock fixed')
